    self.endpoints = tuple(endpoints)

def normalize_routes(self, paths):
    """Preserve the multiset of weighted paths, including repetitions.

    A tuple is both an immutable route plan and a semantic cache identity.
    Object order, bundle order, labels and physical endpoint order vanish.
    """
    if paths is None:
        return None
    bundles = []
    for a, b in self.demand_pairs:
        entries = paths[self.names[a]][self.names[b]]
        # Weight is part of the multiset identity.  A repeated identical
        # path remains repeated; sorting only removes object/bundle order.
        bundle = tuple(sorted((tuple(self.ids[name] for name in entry['path']),
                               entry['weight']) for entry in entries))
        bundles.append(bundle)
    return tuple(bundles)

def compile_routes(self, routes):
    if routes is None:
        return None
    return tuple(tuple((tuple(self.flow_index[a, b] for a, b in zip(path, path[1:])), weight)
                       for path, weight in bundle) for bundle in routes)
